// Demonstrates execution order: sync → microtasks → macrotasks

console.log('1: sync start');

setTimeout(() => console.log('6: macrotask (setTimeout 0)'), 0);

Promise.resolve()
  .then(() => {
    console.log('3: microtask (Promise.then #1)');
    // Enqueuing another microtask inside a microtask:
    Promise.resolve().then(() => console.log('4: microtask (nested .then)'));
  })
  .then(() => console.log('5: microtask (Promise.then #2)'));

queueMicrotask(() => console.log('2.5: microtask (queueMicrotask)'));

console.log('2: sync end');

// Output order:
// 1: sync start
// 2: sync end
// 2.5: microtask (queueMicrotask)
// 3: microtask (Promise.then #1)
// 4: microtask (nested .then)          ← drained before macrotask
// 5: microtask (Promise.then #2)
// 6: macrotask (setTimeout 0)          ← only after ALL microtasks done

// ---- async/await desugared ----
async function fetchData(url) {
  // 'await' suspends here; event loop can run other microtasks
  const response = await fetch(url);    // fetch is a Web API (async)
  const data = await response.json();  // another suspension point
  return data;                          // resumes as microtask when done
}

// Equivalent Promise chain:
function fetchDataPromise(url) {
  return fetch(url)
    .then(response => response.json())
    .then(data => data);
}

// Non-blocking I/O pattern: never block the event loop

// BAD: Synchronous file read blocks the entire event loop
// const data = fs.readFileSync('large-file.csv'); // freezes everything

// GOOD: Async with callback (old style)
const fs = require('fs');
fs.readFile('file.txt', 'utf8', (err, data) => {
  if (err) throw err;
  // runs as a macrotask callback when OS signals I/O complete
  console.log('callback:', data.length, 'bytes');
});

// BETTER: Async with Promise
fs.promises.readFile('file.txt', 'utf8')
  .then(data => console.log('promise:', data.length, 'bytes'))
  .catch(err => console.error(err));

// BEST: Async/await (same event loop behavior, linear readability)
async function processFile() {
  try {
    const data = await fs.promises.readFile('file.txt', 'utf8');
    console.log('async/await:', data.length, 'bytes');
  } catch (err) {
    console.error('Error reading file:', err.message);
  }
}

// Key insight: all three are equivalent in event loop terms.
// async/await is NOT faster — it is equally non-blocking, just easier to read.
